class School:
    def __init__(self):
        self._grades = {}
        self._added = []

    def add_student(self, name, grade):
        if name in self._grades.get(grade, set()):
            self._added.append(False)
            return False
        if name in self._grades.get(grade, set()):
            self._added.append(False)
            return False
        # Check whether the student is already enrolled in any grade.
        for students in self._grades.values():
            if name in students:
                self._added.append(False)
                return False
        self._grades.setdefault(grade, set()).add(name)
        self._added.append(True)
        return True

    def roster(self):
        return [
            name
            for grade in sorted(self._grades)
            for name in sorted(self._grades[grade])
        ]

    def grade(self, grade_number):
        return sorted(self._grades.get(grade_number, set()))

    def added(self):
        return list(self._added)

